61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /** Dedicated audit logger; a successful create emits one line here. */
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    /** Dedicated notification logger; a successful create enqueues one welcome line here. */
74	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
75	
76	    /** Monotonically increasing sequence number stamped onto each structured {@link OwnerCreatedEvent}. */
77	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
78	        new java.util.concurrent.atomic.AtomicLong();
79	
80	    /** Request header carrying the client-supplied key that makes a create idempotent. */
81	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
82	
83	    /**
84	     * Idempotency-Key -> id of the owner originally created under that key. A repeat create carrying an
85	     * already-seen key returns that owner rather than creating a duplicate. Only successful creates are
86	     * recorded here, and the key space is client-supplied, so the map is bounded by distinct keys seen.
87	     */
88	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
89	
90	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
91	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
92	
93	    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
94	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
95	        "mailinator.com", "tempmail.com", "guerrillamail.com");
96	
97	    /**
98	     * Hard per-city capacity: a create into a city that already holds this many owners is rejected
99	     * with {@code 409 CONFLICT}. Counted against the owners already present, before the new one is
100	     * added, matching the basis of {@link #countOwnersInCity(String)}.
101	     */
102	    private static final int CITY_HARD_CAPACITY = 50;
103	
104	    /**
105	     * Soft per-city capacity: the threshold, one band below the {@link #CITY_HARD_CAPACITY hard
106	     * limit}, at which a city is treated as filling up. Counted against the owners already present
107	     * excluding the owner itself; surfaced on responses as {@code capacityWarning} for the band
108	     * between this soft threshold and the hard limit.
109	     */
110	    private static final int CITY_SOFT_CAPACITY = 40;
111	
112	    private final ClinicService clinicService;
113	
114	    private final OwnerMapper ownerMapper;
115	
116	    private final PetMapper petMapper;
117	
118	    private final VisitMapper visitMapper;
119	
120	    public OwnerRestControllerV1(ClinicService clinicService,
121	                                 OwnerMapper ownerMapper,
122	                                 PetMapper petMapper,
123	                                 VisitMapper visitMapper) {
124	        this.clinicService = clinicService;
125	        this.ownerMapper = ownerMapper;
126	        this.petMapper = petMapper;
127	        this.visitMapper = visitMapper;
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
133	        Collection<Owner> owners;
134	        if (lastName != null) {
135	            owners = this.clinicService.findOwnerByLastName(lastName);
136	        } else {
137	            owners = this.clinicService.findAllOwners();
138	        }
139	        if (owners.isEmpty()) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
148	        return withOwner(ownerId, owner ->
149	            new ResponseEntity<>(buildOwnerDto(owner), HttpStatus.OK));
150	    }
151	
152	    /**
153	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
154	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
155	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
156	     */
157	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        return onFound.apply(owner);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
168	        String idempotencyKey = currentIdempotencyKey();
169	        if (idempotencyKey != null) {
170	            Integer existingId = idempotentCreates.get(idempotencyKey);
171	            if (existingId != null) {
172	                Owner existing = this.clinicService.findOwnerById(existingId);
173	                if (existing != null) {
174	                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
175	                }
176	            }
177	        }
178	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
179	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
180	                && response.getBody() != null && response.getBody().getId() != null) {
181	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
182	        }
183	        return response;
184	    }
185	
186	    /**
187	     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
188	     * header is absent or blank. Read from the ambient request rather than the handler signature so the
189	     * generated {@link OwnersApi#addOwner} contract stays unchanged.
190	     */
191	    private static String currentIdempotencyKey() {
192	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
193	            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
194	            if (key != null && !key.isBlank()) {
195	                return key;
196	            }
197	        }
198	        return null;
199	    }
200	
201	    /**
202	     * Run the create pipeline for a new owner from its submitted fields and return the response: the
203	     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
204	     * identity and per-city gates are applied, the derived registration attributes are
205	     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
206	     * its {@code Location}. A gate that trips raises a {@link RequestRejectedException} carrying its own
207	     * status ({@code 400}, {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
208	     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
209	     * of the create pipeline.
210	     */
211	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
212	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
213	        if (!normalizeAndValidateFields(owner)) {
214	            throw new RequestRejectedException(HttpStatus.BAD_REQUEST,
215	                "The submitted owner details are invalid");
216	        }
217	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
218	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
219	            throw new RequestRejectedException(HttpStatus.BAD_REQUEST,
220	                "The registration date cannot be in the future");
221	        }
222	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
223	        owner.setRegistrationDate(registrationDate);
224	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
225	            throw new RequestRejectedException(HttpStatus.TOO_MANY_REQUESTS,
226	                "The daily owner registration limit has been reached");
227	        }
228	        owner.setHouseholdId(householdId(owner));
229	        owner.setIdentityKey(identityKey(owner));
230	        if (isDuplicate(owner)) {
231	            throw new RequestRejectedException(HttpStatus.CONFLICT,
232	                "An owner with the same identity already exists");
233	        }
234	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
235	        if (countOwnersInCity(owner.getCity()) >= CITY_HARD_CAPACITY) {
236	            throw new RequestRejectedException(HttpStatus.CONFLICT,
237	                "The owner's city has reached its capacity");
238	        }
239	        assignRegistrationAttributes(owner, sharesHousehold);
240	        this.clinicService.saveOwner(owner);
241	        auditOwnerCreated(owner);
242	        enqueueWelcomeNotification(owner);
243	        HttpHeaders headers = new HttpHeaders();
244	        headers.setLocation(UriComponentsBuilder.newInstance()
245	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
246	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
247	    }
248	
249	    /**
250	     * Emit the audit trail for a freshly persisted {@code owner} on the dedicated {@code AUDIT}
251	     * logger: the human-readable line followed by the structured {@link OwnerCreatedEvent}. This is
252	     * the one place a created owner's identifiers are read for the audit trail, so a change to which
253	     * identifier is audited is confined here rather than woven through the create pipeline.
254	     */
255	    private void auditOwnerCreated(Owner owner) {
256	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
257	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
258	        AUDIT.info(OwnerCreatedEvent.of(AUDIT_EVENT_SEQ.incrementAndGet(), owner).toJson());
259	    }
260	
261	    /**
262	     * Enqueue the welcome notification for a freshly persisted {@code owner} on the dedicated
263	     * {@code NOTIFY} logger: one line carrying the owner's id and member id, the identifiers a
264	     * downstream notifier needs to greet the new member. Kept separate from the audit trail so the
265	     * notification concern is emitted in one place, after the owner is saved and its id is assigned.
266	     */
267	    private void enqueueWelcomeNotification(Owner owner) {
268	        NOTIFY.info("Welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
269	    }
270	
271	    /**
272	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
273	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
274	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
275	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
276	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
277	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
278	     */
279	    private boolean normalizeAndValidateFields(Owner owner) {
280	        if (!normalizeAddressFields(owner)) {
281	            return false;
282	        }
283	        if (owner.getEmail() != null) {
284	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
285	            if (!EMAIL_PATTERN.matcher(email).matches()) {
286	                return false;
287	            }
288	            if (isDisposableEmailDomain(email)) {
289	                return false;
290	            }
291	            owner.setEmail(email);
292	        }
293	        if (!isPostcodeValidForCity(owner)) {
294	            return false;
295	        }
296	        String telephone = normalizeTelephone(owner.getTelephone());
297	        if (telephone == null) {
298	            return false;
299	        }
300	        owner.setTelephone(telephone);
301	        return true;
302	    }
303	
304	    /**
305	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
306	     * returning whether the owner may proceed to creation. The structured fields are preferred when
307	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
308	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
309	     * composed value (the normalized addressLine1, with a single space and the normalized
310	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
311	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
312	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
313	     * address. This is the single place the owner's address is read, canonicalized and written back,
314	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
315	     */
316	    private boolean normalizeAddressFields(Owner owner) {
317	        String line1 = normalizeAddress(owner.getAddressLine1());
318	        if (!line1.isEmpty()) {
319	            String line2 = normalizeAddress(owner.getAddressLine2());
320	            owner.setAddressLine1(line1);
321	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
322	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
323	            return true;
324	        }
325	        String address = normalizeAddress(owner.getAddress());
326	        if (address.isEmpty()) {
327	            return false;
328	        }
329	        owner.setAddress(address);
330	        return true;
331	    }
332	
333	    /**
334	     * The domain part of {@code email} - everything after the last '@' - or {@code null} when the
335	     * value carries no '@'. The email is already normalized to lower case by the caller, so the
336	     * returned domain is lower-case and ready for a case-insensitive comparison. This is the single
337	     * place an email's domain is carved out, so the checks that compare a domain share it rather
338	     * than each re-scanning for the '@'.
339	     */
340	    private static String emailDomain(String email) {
341	        int at = email.lastIndexOf('@');
342	        return at < 0 ? null : email.substring(at + 1);
343	    }
344	
345	    /**
346	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
347	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
348	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
349	     */
350	    private static boolean isDisposableEmailDomain(String email) {
351	        String domain = emailDomain(email);
352	        return domain != null && DISPOSABLE_EMAIL_DOMAINS.contains(domain);
353	    }
354	
355	    /**
356	     * The registrable second-level labels of the {@link #DISPOSABLE_EMAIL_DOMAINS disposable domains}
357	     * (the label before the final TLD, e.g. {@code "mailinator.com" -> "mailinator"}), used to detect
358	     * domains that are merely disposable-adjacent rather than an exact blocklist match.
359	     */
360	    private static final Set<String> DISPOSABLE_DOMAIN_LABELS = DISPOSABLE_EMAIL_DOMAINS.stream()
361	        .map(OwnerRestControllerV1::secondLevelLabel)
362	        .collect(java.util.stream.Collectors.toUnmodifiableSet());
363	
364	    /**
365	     * The second-level label of {@code domain}: the dot-delimited label immediately before the final
366	     * TLD segment (e.g. {@code "x.mailinator.com" -> "mailinator"}, {@code "mailinator" -> "mailinator"}).
367	     */
368	    private static String secondLevelLabel(String domain) {
369	        String[] labels = domain.split("\\.");
370	        return labels.length >= 2 ? labels[labels.length - 2] : labels[labels.length - 1];
371	    }
372	
373	    /**
374	     * Whether {@code email}'s domain is disposable-adjacent: it is, is a subdomain of, or shares its
375	     * second-level label with a {@link #DISPOSABLE_EMAIL_DOMAINS known disposable domain} - so
376	     * {@code mailinator.com} (exact), {@code x.mailinator.com} (subdomain) and {@code mailinator.net}
377	     * (same label, different TLD) all match, while an unrelated domain does not. A softer signal than
378	     * the exact {@link #isDisposableEmailDomain(String) blocklist} the create gate rejects on, this
379	     * feeds the read-time {@link #isRiskFlag(Owner) risk flag}. A null or {@code '@'}-less email never
380	     * matches.
381	     */
382	    private static boolean isDisposableAdjacentDomain(String email) {
383	        if (email == null) {
384	            return false;
385	        }
386	        String domain = emailDomain(email.trim().toLowerCase(Locale.ROOT));
387	        return domain != null && DISPOSABLE_DOMAIN_LABELS.contains(secondLevelLabel(domain));
388	    }
389	
390	    /**
391	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
392	     * computed against the owner population rather than carried on the owner itself (currently the
393	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
394	     * listing intentionally omits these flags.
395	     */
396	    private OwnerDto buildOwnerDto(Owner owner) {
397	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
398	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
399	        ownerDto.setCapacityWarning(isCapacityWarning(owner));
400	        ownerDto.setRiskFlag(isRiskFlag(owner));
401	        return ownerDto;
402	    }
403	
404	    /**
405	     * Whether {@code owner} should be surfaced as a risk on read: true when any of the risk signals
406	     * hold - the owner is a possible duplicate ({@link Owner#getPossibleDuplicate()}), the owner's
407	     * email domain is {@link #isDisposableAdjacentDomain(String) disposable-adjacent}, or the owner's
408	     * city is over its soft capacity ({@link #isCapacityWarning(Owner)}); otherwise false. Each signal
409	     * reuses the rule that owns it rather than re-deriving it here.
410	     */
411	    private boolean isRiskFlag(Owner owner) {
412	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
413	            || isDisposableAdjacentDomain(owner.getEmail())
414	            || isCapacityWarning(owner);
415	    }
416	
417	    /**
418	     * Whether {@code owner}'s city is approaching its per-city capacity limit: it already holds between
419	     * 40 and 49 other owners, one short of the hard limit of 50 at which creation is rejected.
420	     * Surfaced on responses as {@code capacityWarning}. Computed against the current owner population
421	     * excluding this owner, so the count basis mirrors the per-city create gate (which counts the
422	     * owners already present, before the new one is added).
423	     */
424	    private boolean isCapacityWarning(Owner owner) {
425	        long othersInCity = countOtherOwnersInCity(owner);
426	        return othersInCity >= CITY_SOFT_CAPACITY && othersInCity < CITY_HARD_CAPACITY;
427	    }
428	
429	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
430	    @Override
431	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
432	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
433	        if (currentOwner == null) {
434	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
435	        }
436	        currentOwner.setAddress(ownerFieldsDto.getAddress());
437	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
438	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
439	        currentOwner.setCity(ownerFieldsDto.getCity());
440	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
441	        currentOwner.setLastName(ownerFieldsDto.getLastName());
442	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
443	        String email = ownerFieldsDto.getEmail();
444	        if (email != null) {
445	            email = email.trim().toLowerCase(Locale.ROOT);
446	            if (!EMAIL_PATTERN.matcher(email).matches()) {
447	                throw new RequestRejectedException(HttpStatus.BAD_REQUEST,
448	                    "The submitted email address is not valid");
449	            }
450	        }
451	        currentOwner.setEmail(email);
452	        this.clinicService.saveOwner(currentOwner);
453	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
