625	    /**
626	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
627	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
628	     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
629	     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
630	     * matching owner's id. Runs before save, against the existing owner population.
631	     */
632	    private void assignPossibleDuplicate(Owner owner) {
633	        Integer matchId = findPossibleDuplicateOf(owner);
634	        owner.setPossibleDuplicate(matchId != null);
635	        owner.setPossibleDuplicateOf(matchId);
636	    }
637	
638	    /**
639	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
640	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
641	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
642	     * with the same last name and postcode but different telephones differ in key and so match here,
643	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
644	     * the lowest id is returned. An owner without a postcode never matches.
645	     */
646	    private Integer findPossibleDuplicateOf(Owner owner) {
647	        String postcode = owner.getPostcode();
648	        if (postcode == null) {
649	            return null;
650	        }
651	        String soundex = soundex(owner.getLastName());
652	        String identityKey = owner.getIdentityKey();
653	        return this.clinicService.findAllOwners().stream()
654	            .filter(existing -> !existing.isDeleted())
655	            .filter(existing -> existing.getId() != null
656	                && postcode.equals(existing.getPostcode())
657	                && soundex(existing.getLastName()).equals(soundex)
658	                && !identityKey.equals(existing.getIdentityKey()))
659	            .map(Owner::getId)
660	            .min(Integer::compareTo)
661	            .orElse(null);
662	    }
663	
664	    /**
665	     * Build {@code owner}'s member id '<REGION><FY><HASH8><CHK>': REGION is the region code derived
666	     * from the owner's postcode ({@link Owner#getRegion()}), FY the two-digit
667	     * {@link Owner#fiscalYearSegment(LocalDate) fiscal-year segment} of the business-day-adjusted
668	     * {@link Owner#getRegistrationDate() registration date}, HASH8 the first 8 upper-case hex
669	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
670	     * owner's last name, and CHK a single {@link Owner#luhnCheckDigit(String) Luhn check digit} over
671	     * the digits of '<REGION><FY><HASH8>' (e.g. 'NSW271A2B3C4D5'). The identity is otherwise a pure
672	     * function of the region, fiscal year and the (telephone, last name) pair; only when the computed
673	     * id collides with an existing owner's member id is it de-duplicated by appending '-<n>' with the
674	     * smallest {@code n} of 2 or more that makes it unique (e.g. 'NSW271A2B3C4D5-2').
675	     */
676	    private String generateMemberId(Owner owner) {
677	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
678	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
679	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
680	        String core = owner.getRegion() + Owner.fiscalYearSegment(owner.getRegistrationDate()) + hash8;
681	        String base = core + Owner.luhnCheckDigit(core);
682	        return deduplicateMemberId(base);
683	    }
684	
685	    /**
686	     * De-duplicate a computed member id against the existing owner population: when {@code base}
687	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
688	     * {@code n} of 2 or more that yields an id no existing owner carries.
689	     */
690	    private String deduplicateMemberId(String base) {
691	        Set<String> existing = this.clinicService.findAllOwners().stream()
692	            .map(Owner::getMemberId)
693	            .filter(code -> code != null)
694	            .collect(java.util.stream.Collectors.toSet());
695	        if (!existing.contains(base)) {
696	            return base;
697	        }
698	        int n = 2;
699	        while (existing.contains(base + "-" + n)) {
700	            n++;
701	        }
702	        return base + "-" + n;
703	    }
