729	    /**
730	     * The effective registration date to store for a new owner: the date supplied on the request
731	     * when present, otherwise the current server date, in either case rolled forward to a business
732	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
733	     * This single point of resolution is what every registration-date-derived value (the stored
734	     * date, the member id's fiscal-year segment, the per-day create-limit) is computed from.
735	     */
736	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
737	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
738	        return toBusinessDay(date);
739	    }
740	
741	    /**
742	     * The fixed list of public holidays that a registration date must not fall on. A date landing
743	     * on one of these is rolled forward, exactly as weekends are.
744	     */
745	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
746	        LocalDate.of(2026, 1, 1),
747	        LocalDate.of(2026, 1, 26),
748	        LocalDate.of(2026, 4, 25),
749	        LocalDate.of(2026, 12, 25),
750	        LocalDate.of(2026, 12, 28));
751	
752	    /**
753	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
754	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
755	     * unchanged.
756	     */
757	    private static LocalDate toBusinessDay(LocalDate date) {
758	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
759	                || PUBLIC_HOLIDAYS.contains(date)) {
760	            date = date.plusDays(1);
761	        }
762	        return date;
763	    }
