794	    /**
795	     * The single derived key all duplicate detection flows through: the lower-case hex SHA-256 of
796	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, formed from the
797	     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
798	     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
799	     * the telephone is part of the key, two owners with the same last name and postcode but
800	     * different telephones resolve to different keys and are both allowed (the later one becoming a
801	     * possible duplicate rather than a hard conflict).
802	     */
803	    private static String identityKey(Owner owner) {
804	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
805	        String email = owner.getEmail() == null ? "" : owner.getEmail();
806	        String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
807	        return Owner.sha256HexLower(key);
808	    }
809	
810	    /**
811	     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
812	     * the sole duplicate condition: the previously separate telephone, email and household checks -
813	     * including the household-duplicate check derived from the {@code householdId} - are now all
814	     * expressed through this one identity key, so only an exact key match is a duplicate and a create
815	     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
816	     */
817	    private boolean isDuplicate(Owner owner) {
818	        String key = owner.getIdentityKey();
819	        return this.clinicService.findAllOwners().stream()
820	            .filter(existing -> !existing.isDeleted())
821	            .map(Owner::getIdentityKey)
822	            .filter(existing -> existing != null)
823	            .anyMatch(key::equals);
824	    }
