826	    /** Common street-type abbreviations expanded during address normalization. */
827	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
828	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
829	
830	    /**
831	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
832	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
833	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
834	     * string when {@code address} is null or blank after normalization.
835	     */
836	    private static String normalizeAddress(String address) {
837	        if (address == null) {
838	            return "";
839	        }
840	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
841	        if (collapsed.isEmpty()) {
842	            return "";
843	        }
844	        StringBuilder sb = new StringBuilder(collapsed.length());
845	        for (String token : collapsed.split(" ")) {
846	            if (sb.length() > 0) {
847	                sb.append(' ');
848	            }
849	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
850	        }
851	        return sb.toString();
852	    }
853	
854	    /**
855	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
856	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
857	     */
858	    private static String normalizeHouseholdField(String value) {
859	        if (value == null) {
860	            return "";
861	        }
862	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
863	    }
864	
865	    /**
866	     * The American Soundex code of {@code value}: the retained first letter followed by up to three
867	     * digits encoding the remaining consonants, right-padded with zeros to length four. Non-letters
868	     * are ignored, adjacent letters coding to the same digit (including when separated by 'H' or 'W')
869	     * are coded once, and vowels (with 'Y') act as separators. Returns the empty string when
870	     * {@code value} holds no letters. Phonetically similar last names share a code, which is what the
871	     * identity key and the possible-duplicate soft match compare on.
872	     */
873	    private static String soundex(String value) {
874	        if (value == null) {
875	            return "";
876	        }
877	        StringBuilder letters = new StringBuilder();
878	        for (char c : value.toCharArray()) {
879	            if (c < 128 && Character.isLetter(c)) {
880	                letters.append(Character.toUpperCase(c));
881	            }
882	        }
883	        if (letters.length() == 0) {
884	            return "";
885	        }
886	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
887	        char previous = soundexDigit(letters.charAt(0));
888	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
889	            char c = letters.charAt(i);
890	            if (c == 'H' || c == 'W') {
891	                continue;
892	            }
893	            char digit = soundexDigit(c);
894	            if (digit != '0' && digit != previous) {
895	                code.append(digit);
896	            }
897	            previous = digit;
898	        }
899	        while (code.length() < 4) {
900	            code.append('0');
901	        }
902	        return code.toString();
903	    }
