905	    /** The Soundex digit for an upper-case letter, or {@code '0'} for letters that are not coded. */
906	    private static char soundexDigit(char c) {
907	        switch (c) {
908	            case 'B': case 'F': case 'P': case 'V':
909	                return '1';
910	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
911	                return '2';
912	            case 'D': case 'T':
913	                return '3';
914	            case 'L':
915	                return '4';
916	            case 'M': case 'N':
917	                return '5';
918	            case 'R':
919	                return '6';
920	            default:
921	                return '0';
922	        }
923	    }
