925	    /**
926	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
927	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
928	     * key rather than re-derived from the underlying fields here, so the household is described in one
929	     * place and every household-keyed value stays consistent with it.
930	     */
931	    private List<Owner> findHousemates(Owner owner) {
932	        String householdId = householdId(owner);
933	        return this.clinicService.findAllOwners().stream()
934	            .filter(existing -> !existing.isDeleted())
935	            .filter(existing -> householdId(existing).equals(householdId))
936	            .toList();
937	    }
