939	    /**
940	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
941	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
942	     */
943	    private int countHouseholdMembers(Owner owner) {
944	        return findHousemates(owner).size() + 1;
945	    }
