947	    /**
948	     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
949	     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
950	     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
951	     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
952	     * applies - when the owner has no existing household member.
953	     */
954	    private Integer membershipLevelCapForHousehold(Owner owner) {
955	        OptionalInt maxLevel = findHousemates(owner).stream()
956	            .mapToInt(Owner::getMembershipLevel)
957	            .max();
958	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
959	    }
