961	    /**
962	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
963	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
964	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
965	     * string standing in for a missing postcode), so housemates always resolve to the same value
966	     * regardless of registration order, and owners sharing a last name and postcode share it
967	     * automatically.
968	     */
969	    private static String householdId(Owner owner) {
970	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
